function rampartSimulate(createStrategy, seed, maxTicks, rec) {
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return (t ^ (t >>> 14)) >>> 0; }; }
  const TT = {
    bolt:{cost:50,dmg:26,per:8,range:300,splash:0,slow:0,pierce:0,g:1,a:1,idx:0},
    cannon:{cost:90,dmg:60,per:24,range:260,splash:90,slow:0,pierce:0,g:1,a:0,idx:1},
    frost:{cost:70,dmg:10,per:12,range:240,splash:0,slow:30,pierce:0,g:1,a:1,idx:2},
    lance:{cost:120,dmg:180,per:36,range:360,splash:0,slow:0,pierce:1,g:1,a:0,idx:3},
    flak:{cost:80,dmg:40,per:10,range:320,splash:70,slow:0,pierce:0,g:0,a:1,idx:4}};
  const EE = {
    grunt:{hp:60,spd:10,bounty:4,leak:1,air:0,first:1,wt:10},
    runner:{hp:40,spd:20,bounty:4,leak:1,air:0,first:2,wt:4},
    wisp:{hp:50,spd:12,bounty:6,leak:2,air:1,first:3,wt:3},
    brute:{hp:150,spd:6,bounty:9,leak:3,air:0,first:4,wt:3},
    splitter:{hp:90,spd:8,bounty:6,leak:2,air:0,first:6,wt:2},
    mender:{hp:70,spd:8,bounty:7,leak:2,air:0,first:8,wt:1},
    splitling:{hp:1,spd:12,bounty:1,leak:1,air:0,first:99,wt:0}};
  const ORDER = ["grunt","runner","wisp","brute","splitter","mender"];
  const SLOTS = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[19,8],[20,10],[22,9],[3,7]].slice(0);
  SLOTS.splice(11,0,[17,4]); SLOTS.splice(10,0,[16,7]); SLOTS.length = 0;
  [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],[14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]].forEach(s=>SLOTS.push(s));
  function mk(pts){ const p=pts.map(q=>[q[0]*100+50,q[1]*100+50]); const cum=[0];
    for(let i=1;i<p.length;i++) cum.push(cum[i-1]+Math.abs(p[i][0]-p[i-1][0])+Math.abs(p[i][1]-p[i-1][1]));
    return {p,cum,len:cum[cum.length-1]}; }
  const ROUTES=[mk([[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]]), mk([[0,6],[21,6],[21,11],[23,11]])];
  function posAt(r,pr){ if(pr>=r.len) pr=r.len; let i=1; while(i<r.p.length-1&&pr>r.cum[i]) i++;
    const a=r.p[i-1],b=r.p[i],l=r.cum[i]-r.cum[i-1]; const f=l?(pr-r.cum[i-1])/l:0;
    return [Math.floor(a[0]+(b[0]-a[0])*f), Math.floor(a[1]+(b[1]-a[1])*f)]; }
  const M=[0,1000]; function mult(w){ while(M.length<=w) M.push(Math.floor(M[M.length-1]*108/100)); return M[w]; }
  const rng=mulberry32(seed), waves={};
  function gen(w){ const av=ORDER.filter(t=>EE[t].first<=w); let sum=0; av.forEach(t=>sum+=EE[t].wt);
    const n=4+Math.floor(3*w/5), arr=[];
    for(let i=0;i<n;i++){ let r=rng()%sum; for(const t of av){ if(r<EE[t].wt){arr.push(t);break;} r-=EE[t].wt; } }
    waves[w]=arr; }
  gen(1);
  const strat=createStrategy();
  let gold=250, baseHp=10, nextId=1, enemies=[], queue=[], curWave=0;
  const turrets=new Array(16).fill(null), log=[];
  function armor(e){ return e.type==="grunt"?Math.floor(e.wave/4):e.type==="brute"?6+e.wave:0; }
  function spawn(type,wave,hp,prog){ const d=EE[type]; const maxHp=hp!==null?hp:Math.floor(d.hp*mult(wave)/1000);
    const e={id:nextId++,type,wave,hp:maxHp,maxHp,prog:prog||0,age:0,slow:0,route:d.air,x:0,y:0};
    enemies.push(e); return e; }
  function upd(e){ const p=posAt(ROUTES[e.route],e.prog); e.x=p[0]; e.y=p[1]; }
  function view(e){ upd(e); const d=EE[e.type]; return {id:e.id,type:e.type,hp:e.hp,maxHp:e.maxHp,x:e.x,y:e.y,air:d.air,armor:armor(e),
    speed:e.slow>0?Math.floor(d.spd*60/100):d.spd,slowed:e.slow>0?1:0,remaining:ROUTES[e.route].len-e.prog}; }
  function trange(t){ return TT[t.type].range+30*(t.tier-1); }
  function tdmg(t){ let d=TT[t.type].dmg; for(let i=1;i<t.tier;i++) d=Math.floor(d*16/10); return d; }
  let fallTick=-1, endTick=maxTicks, shots=[], kills=[], leaks=[], builds=[];
  for(let t=0;t<maxTicks;t++){
    shots=[];kills=[];leaks=[];builds=[];
    if(t>=20&&(t-20)%40===0){
      const w=(t-20)/40+1; curWave=w;
      gold+=Math.min(50,Math.floor(gold*5/100))+10+2*w;
      gen(w+1);
      const st={tick:t,wave:w,gold,baseHp,
        slots:SLOTS.map((s,i)=>({slot:i,x:s[0],y:s[1],turret:turrets[i]?{type:turrets[i].type,tier:turrets[i].tier,spent:turrets[i].spent}:null})),
        enemies:enemies.map(view),nextWave:waves[w+1].slice()};
      let acts=strat.plan(st); if(!Array.isArray(acts)) acts=[];
      acts=acts.slice(0,32);
      for(const a of acts){ if(!a) continue; const s=a.slot;
        if(!(s>=0&&s<16&&Number.isInteger(s))) continue;
        if(a.op==="build"){ const d=TT[a.type]; if(!d||turrets[s]||gold<d.cost) continue;
          gold-=d.cost; turrets[s]={type:a.type,tier:1,spent:d.cost,cd:0}; log.push([t,"B",s,d.idx]); builds.push(["B",s]); }
        else if(a.op==="upgrade"){ const u=turrets[s]; if(!u||u.tier>=3) continue; const c=TT[u.type].cost*u.tier;
          if(gold<c) continue; gold-=c; u.spent+=c; u.tier++; log.push([t,"U",s,u.tier]); builds.push(["U",s]); }
        else if(a.op==="sell"){ const u=turrets[s]; if(!u) continue; gold+=Math.floor(u.spent*70/100); turrets[s]=null; log.push([t,"S",s,0]); builds.push(["S",s]); } }
      for(let i=0;i<waves[w].length;i++) queue.push({tick:t+4*i,wave:w,idx:i,type:waves[w][i]});
      queue.sort((a,b)=>a.tick-b.tick||a.wave-b.wave||a.idx-b.idx);
    }
    while(queue.length&&queue[0].tick<=t){ const q=queue.shift(); spawn(q.type,q.wave,null,0); }
    // move
    let fell=false;
    for(const e of enemies){ const d=EE[e.type]; e.prog+=e.slow>0?Math.floor(d.spd*60/100):d.spd;
      if(e.prog>=ROUTES[e.route].len){ e.dead=1; baseHp-=d.leak; log.push([t,"L",e.id,baseHp]); leaks.push(e.id);
        if(baseHp<=0){ fell=true; break; } } }
    if(fell){ log.push([t,"F",curWave,0]); fallTick=t; endTick=t; frame(t); break; }
    enemies=enemies.filter(e=>!e.dead);
    // age & heal
    for(const e of enemies){ e.age++; if(e.type==="mender"&&e.age%20===0){ upd(e);
      for(const o of enemies){ upd(o); const dx=o.x-e.x,dy=o.y-e.y; if(dx*dx+dy*dy<=22500) o.hp=Math.min(o.maxHp,o.hp+Math.floor(o.maxHp*8/100)); } } }
    // turrets
    for(let s=0;s<16;s++){ const u=turrets[s]; if(!u) continue;
      if(u.cd>0) u.cd--; if(u.cd>0) continue;
      const d=TT[u.type], r=trange(u), sx=SLOTS[s][0]*100+50, sy=SLOTS[s][1]*100+50;
      const cands=[];
      for(const e of enemies){ if(e.hp<=0) continue; const ed=EE[e.type]; if(ed.air?!d.a:!d.g) continue; upd(e);
        const dx=e.x-sx,dy=e.y-sy; if(dx*dx+dy*dy<=r*r) cands.push(e); }
      if(!cands.length) continue;
      let tg=null;
      if(strat.target){ const id=strat.target({slot:s,type:u.type,tier:u.tier,x:sx,y:sy,range:r},cands.map(view)); tg=cands.find(c=>c.id===id)||null; }
      if(!tg){ tg=cands[0]; let br=ROUTES[tg.route].len-tg.prog; for(const c of cands){ const rm=ROUTES[c.route].len-c.prog; if(rm<br){br=rm;tg=c;} } }
      const dm=tdmg(u); const hit=[];
      if(d.splash>0){ for(const e of enemies){ if(e.hp<=0) continue; const ed=EE[e.type]; if(ed.air?!d.a:!d.g) continue; upd(e);
        const dx=e.x-tg.x,dy=e.y-tg.y; if(dx*dx+dy*dy<=d.splash*d.splash) hit.push(e); } } else hit.push(tg);
      for(const e of hit){ e.hp-=d.pierce?dm:Math.max(1,dm-armor(e)); if(d.slow) e.slow=d.slow; }
      u.cd=d.per; shots.push({slot:s,type:d.idx,tier:u.tier,tid:tg.id,x:tg.x,y:tg.y});
      const dead=enemies.filter(e=>e.hp<=0);
      for(const e of dead){ gold+=EE[e.type].bounty; log.push([t,"K",e.id,s]); kills.push({id:e.id,type:e.type,x:e.x,y:e.y,slot:s});
        if(e.type==="splitter"){ const h=Math.max(1,Math.floor(e.maxHp/4)); for(let k=0;k<3;k++){ const n=spawn("splitling",e.wave,h,e.prog); upd(n);} } }
      if(dead.length) enemies=enemies.filter(e=>e.hp>0);
    }
    for(const e of enemies) if(e.slow>0) e.slow--;
    frame(t);
  }
  function frame(t){ if(!rec) return; rec(t,{wave:curWave,gold,baseHp,
    en:enemies.map(e=>{upd(e);return [e.id,e.type,e.x,e.y,e.hp,e.maxHp,e.slow>0?1:0,e.route];}),
    tu:turrets.map(u=>u?TT[u.type].idx*4+u.tier:0),shots,kills,leaks,builds,
    next:waves[curWave+1]||waves[1]}); }
  let h=0x811c9dc5; const js=JSON.stringify(log);
  for(let i=0;i<js.length;i++){ h^=js.charCodeAt(i); h=Math.imul(h,0x01000193); }
  return {score:Math.round((endTick-20)/40*100)/100,fallTick,log,hash:(h>>>0).toString(16).padStart(8,"0")};
}
